import { Router } from 'express';
import * as predictionController from '../controllers/prediction.controller';
import { requireAuth } from '../middlewares/auth.middleware';

const router = Router();

router.use(requireAuth);

/**
 * @openapi
 * /predictions:
 *   get:
 *     tags: [Predictions]
 *     summary: Get latest AI predictions
 *     description: Returns the cached 30-day cash flow forecast generated by the AI model.
 *     security:
 *       - BearerAuth: []
 *     responses:
 *       200:
 *         description: List of daily predictions for the next 30 days
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 status:
 *                   type: string
 *                   example: success
 *                 data:
 *                   type: array
 *                   items:
 *                     type: object
 *                     properties:
 *                       id:
 *                         type: string
 *                         format: uuid
 *                       forecast_date:
 *                         type: string
 *                         format: date
 *                       predicted_amount:
 *                         type: string
 *                         description: Decimal value
 *                       confidence_score:
 *                         type: number
 *                         description: Between 0 and 1
 *                       generated_at:
 *                         type: string
 *                         format: date-time
 */
router.get('/', predictionController.getPredictions);

/**
 * @openapi
 * /predictions/generate:
 *   post:
 *     tags: [Predictions]
 *     summary: Generate new AI predictions
 *     description: |
 *       Triggers the AI service to generate a new 30-day cash flow forecast.
 *       Old predictions are replaced. Also checks for early warnings based on user budgets.
 *       **Note:** Currently using mock data until the FastAPI AI service is deployed.
 *     security:
 *       - BearerAuth: []
 *     responses:
 *       201:
 *         description: Predictions generated successfully
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 status:
 *                   type: string
 *                   example: success
 *                 message:
 *                   type: string
 *                 data:
 *                   type: array
 *                   items:
 *                     type: object
 */
router.post('/generate', predictionController.generatePrediction);

/**
 * @openapi
 * /predictions/warning:
 *   get:
 *     tags: [Predictions]
 *     summary: Check early warning status
 *     description: Compares predicted expenses with budget limits to determine if the user is at risk of overspending.
 *     security:
 *       - BearerAuth: []
 *     responses:
 *       200:
 *         description: Early warning status
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 status:
 *                   type: string
 *                 data:
 *                   type: object
 *                   properties:
 *                     actualExpense:
 *                       type: number
 *                     predictedExpense:
 *                       type: number
 *                     projectedTotal:
 *                       type: number
 *                     totalBudget:
 *                       type: number
 *                     isOverBudget:
 *                       type: boolean
 */
router.get('/warning', predictionController.getWarningStatus);

/**
 * @openapi
 * /predictions/ai-result:
 *   get:
 *     tags: [Predictions]
 *     summary: Get latest AI analysis result
 *     description: Returns the most recent real LSTM prediction result (AMAN/BAHAYA status, risk probability, recommendation).
 *     security:
 *       - BearerAuth: []
 *     responses:
 *       200:
 *         description: Latest AI analysis result
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 status:
 *                   type: string
 *                 data:
 *                   type: object
 *                   properties:
 *                     ai_status:
 *                       type: string
 *                       description: "AMAN, BAHAYA, INSUFFICIENT_DATA, or UNAVAILABLE"
 *                     risk_probability:
 *                       type: number
 *                       description: Between 0.0 and 1.0
 *                     rekomendasi:
 *                       type: string
 *                     model_digunakan:
 *                       type: string
 *                     generated_at:
 *                       type: string
 *                       format: date-time
 */
router.get('/ai-result', predictionController.getAiAnalysisResult);

export default router;
